  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 2 },
      { sku: 'STICKER', qty: 50 },
    ],
  });

  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 8 × 9500 = 76000
  // DES-HOUR: 3 × 8500 = 25500
  // ICON-SET: 2 × 980 = 1960
  // STICKER: 50 × 50 = 2500
  // Subtotal: 105960
  // C-001 is gold tier (5% discount): 105960 × 5 / 100 = 5298
  // Total: 105960 - 5298 = 100662
  assert.equal(totals.subtotal, 105960);
  assert.equal(totals.discount, 5298);
  assert.equal(totals.total, 100662);
});

