test('invoiceTotals sums multiple line items', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 10 × 9500 = 95000
  // DES-HOUR: 5 × 8500 = 42500
  // Subtotal: 137500
  // C-001 is gold tier (5% discount): 137500 × 5 / 100 = 6875
  // Total: 137500 - 6875 = 130625
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.discount, 6875);
  assert.equal(totals.total, 130625);
