  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.total, 90250);
});

test('invoiceTotals with different tier discounts', () => {
  // C-003 is silver tier (2.5%)
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);
  // subtotal = 95000
  // discount = 95000 × 2.5 / 100 = 2375
  // taxable = 95000 - 2375 = 92625
  // VAT = 92625 × 21 / 100 = 19451.25 → 19451 (banker's rounding)
  // total = 95000 - 2375 + 19451 = 112076
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 2375);
  assert.equal(totals.vat, 19451);
  assert.equal(totals.total, 112076);
});

