  // lineTotal = 10 × 9500 = 95000
  // discount = 95000 × 10 / 100 = 9500
  // taxable amount = 95000 - 9500 = 85500
  // VAT = 85500 × 21 / 100 = 17955
  assert.equal(lineVAT(line), 17955);
});

