test('invoiceTotals with single expensive item', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 1 }],
  });

  const totals = invoiceTotals(result.value);
  // Subtotal: 245000
  // C-001 is gold tier (5% discount): 12250
  // Taxable: 232750
  // VAT (21%): 232750 × 21 / 100 = 48877.5 → 48878 (banker's rounding)
  // Total: 245000 - 12250 + 48878 = 281628
  assert.equal(totals.subtotal, 245000);
  assert.equal(totals.discount, 12250);
  assert.equal(totals.vat, 48878);
  assert.equal(totals.total, 281628);
