    ],
  });

  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 95000, discount 10% = 9500, taxable = 85500, VAT 21% = 17955
  // DES-HOUR: 42500, discount 20% = 8500, taxable = 34000, VAT 21% = 7140
  // subtotal = 137500, total discount = 18000, total VAT = 25095
  // total = 137500 - 18000 + 25095 = 144595
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.discount, 18000);
  assert.equal(totals.vat, 25095);
  assert.equal(totals.total, 144595);
});

